import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        if ((n * m < 4 && (n == 1 || m == 1)) || (n * m < 5 && (n != 1 && m != 1))) {
            System.out.println(0);
        } else {
            int l = n * m;
            if (n % 2 == 0 && m % 2 == 0) {
                if (n == m) {
                    if (n % 3 != 0 && n % 4 != 0) {
                        System.out.println(l - 4);
                    } else {
                        System.out.println(l);
                    }
                } else {
                    if (n % 4 == 0 || m % 4 == 0) {
                        System.out.println(l);
                    } else if (n % 3 == 0 || m % 3 == 0) {
                        System.out.println(l);
                    } else {
                        System.out.println(l - 2);
                    }
                }
            } else if (n % 2 != 0 && m % 2 != 0) {
                if (n == 1 || m == 1) {
                    int z = Math.max(n, m);
                    if (z % 6 == 0) {
                        System.out.println(z);
                    } else {
                        int s1 = (z / 6) * 6;
                        int r = z % 6;
                        if (r > 3) {
                            s1 = s1 + 2;
                            r = r % 4;
                            s1 = s1 + (r * 2);
                        }
                        System.out.println(s1);
                    }
                } else {
                    System.out.println(l - 1);
                }
            } else {
                // case 3: one even, one odd
                if (n == 1 || m == 1) {
                    int z = Math.max(n, m);
                    if (z % 6 == 0) {
                        System.out.println(z);
                    } else {
                        int s1 = (z / 6) * 6;
                        int r = z % 6;
                        if (r > 3) {
                            s1 = s1 + 2;
                            r = r % 4;
                            s1 = s1 + (r * 2);
                        }
                        System.out.println(s1);
                    }
                } else {
                    if (n % 4 == 0 || m % 4 == 0) {
                        System.out.println(l);
                    } else if (n % 6 == 0 || m % 6 == 0) {
                        System.out.println(l);
                    } else {
                        int z;
                        if (n % 2 == 0) {
                            z = m;
                        } else {
                            z = n;
                        }
                        if (z % 4 == 1) {
                            System.out.println(l);
                        } else {
                            if (z >= 6) {
                                if (z % 6 == 1) {
                                    if (z > 7 && z % 4 == 3) {
                                        System.out.println(l);
                                    } else {
                                        System.out.println(l - 2);
                                    }
                                } else if (z % 6 == 5 && z % 4 == 3) {
                                    System.out.println(l);
                                } else if (z % 6 == 3) {
                                    System.out.println(l);
                                }
                            } else {
                                System.out.println(l - 2);
                            }
                        }
                    }
                }
            }
        }
        scanner.close();
    }
}
